class OperatorError(RuntimeError):
    """Fail-closed ASEH program error."""


class OperatorStopRequested(OperatorError):
    """The operator received an orderly process-stop signal."""

    def __init__(self, signum: int) -> None:
        self.signum = int(signum)
        super().__init__(f"operator stop requested by signal {self.signum}")


@contextmanager
def _stop_signal_handlers(
    requested: threading.Event,
    received: dict[str, int],
    *,
    survive_external_sigterm: bool = False,
) -> Any:
    """Install reversible SIGINT/SIGTERM handlers for orderly shutdown.

    ``survive_external_sigterm`` is for exclusive owners whose lifetime is
    bound to the board. Session compaction sends SIGTERM to the wrapper,
    which previously forwarded it and then SIGKILL'd the sealed child.
    SIGINT still requests stop.
    """

    if threading.current_thread() is not threading.main_thread():
        yield
        return
    prior: dict[int, Any] = {}
    caught = (signal.SIGINT,)
    if not survive_external_sigterm:
        caught = (signal.SIGINT, signal.SIGTERM)

    def request_stop(signum: int, _frame: Any) -> None:
        received.setdefault("signum", int(signum))
        requested.set()

    try:
        if survive_external_sigterm:
            # Omitting a SIGTERM handler restores SIG_DFL and kills the
            # exclusive-owner wrapper. Ignore it instead so session
            # compaction cannot tear down a healthy board.
            prior[signal.SIGTERM] = signal.getsignal(signal.SIGTERM)
            signal.signal(signal.SIGTERM, signal.SIG_IGN)
        for signum in caught:
            prior[signum] = signal.getsignal(signum)
            signal.signal(signum, request_stop)
        yield
    finally:
        for signum, handler in prior.items():
            signal.signal(signum, handler)


def _canonical_bytes(value: Any) -> bytes:
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False,
        allow_nan=False,
    ).encode("utf-8")


def _identity(value: Any) -> str:
    payload = value if isinstance(value, bytes) else _canonical_bytes(value)
    return "sha256:" + hashlib.sha256(payload).hexdigest()


def _atomic_json(path: Path, payload: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.tmp.{os.getpid()}")
    descriptor = os.open(
        temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600
    )
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            handle.write(json.dumps(payload, indent=2, sort_keys=True) + "\n")
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        os.chmod(path, 0o600)
    except BaseException:
        temporary.unlink(missing_ok=True)
        raise


def _same_namespace_identity(
    left: os.stat_result,
    right: os.stat_result,
) -> bool:
    return bool(
        left.st_dev == right.st_dev
        and left.st_ino == right.st_ino
        and left.st_mode == right.st_mode
        and left.st_uid == right.st_uid
        and left.st_nlink == right.st_nlink
    )


@contextmanager
def _anchored_directory_descriptor(directory: Path) -> Any:
    """Retain and revalidate every directory inode from ``/`` to a target."""

    absolute = Path(os.path.abspath(directory))
    if not absolute.is_absolute():
        raise OperatorError("runtime authority directory is not absolute")
    flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    descriptors: list[int] = []
    edges: list[tuple[int, str, int]] = []
    verification_error: BaseException | None = None
    try:
        root_fd = os.open(os.sep, flags)
        descriptors.append(root_fd)
        root_named = os.stat(os.sep, follow_symlinks=False)
        root_opened = os.fstat(root_fd)
        if (
            not stat.S_ISDIR(root_opened.st_mode)
            or not _same_namespace_identity(root_named, root_opened)
        ):
            raise OperatorError("filesystem root directory identity is unsafe")
        parent_fd = root_fd
        for component in absolute.parts[1:]:
            if not component or component in {".", ".."} or "/" in component:
                raise OperatorError("runtime authority directory component is unsafe")
            child_fd = os.open(component, flags, dir_fd=parent_fd)
            descriptors.append(child_fd)
            named = os.stat(
                component,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
            opened = os.fstat(child_fd)
            if (
                not stat.S_ISDIR(opened.st_mode)
                or not _same_namespace_identity(named, opened)
            ):
                raise OperatorError("runtime authority directory identity is unsafe")
            edges.append((parent_fd, component, child_fd))
            parent_fd = child_fd
        final = os.fstat(parent_fd)
        if final.st_uid != os.geteuid():
            raise OperatorError("runtime authority directory owner differs")
        yield parent_fd
    finally:
        try:
            if descriptors:
                root_named = os.stat(os.sep, follow_symlinks=False)
                if not _same_namespace_identity(
                    root_named,
                    os.fstat(descriptors[0]),
                ):
                    raise OperatorError(
                        "filesystem root directory changed during authority use"
                    )
                for parent_fd, component, child_fd in edges:
                    named = os.stat(
                        component,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                    if not _same_namespace_identity(named, os.fstat(child_fd)):
                        raise OperatorError(
                            "runtime authority directory changed during use"
                        )
        except BaseException as exc:
            verification_error = exc
        finally:
            for descriptor in reversed(descriptors):
                os.close(descriptor)
        if verification_error is not None:
            raise verification_error


def _rename_noreplace(
    directory_fd: int,
    source_name: str,
    target_name: str,
) -> None:
    """Atomically publish one name without an overwrite-capable fallback."""

    renameat2 = getattr(ctypes.CDLL(None, use_errno=True), "renameat2", None)
    if renameat2 is None:
        raise OperatorError("immutable receipt publication requires renameat2")
    renameat2.argtypes = (
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_uint,
    )
    renameat2.restype = ctypes.c_int
    result = renameat2(
        directory_fd,
        os.fsencode(source_name),
        directory_fd,
        os.fsencode(target_name),
        1,  # RENAME_NOREPLACE
    )
    if result == 0:
        return
    error = ctypes.get_errno()
    if error == errno.EEXIST:
        raise OperatorError(
            "immutable runtime receipt already exists; reload and validate it"
        )
    raise OSError(error, os.strerror(error), target_name)


def _atomic_json_create(
    path: Path,
    payload: Mapping[str, Any],
    *,
    authority_directory_fd: int | None = None,
) -> None:
    """Descriptor-relatively publish and verify one create-only JSON object."""

    path.parent.mkdir(parents=True, exist_ok=True)
    if path.name in {"", ".", ".."} or "/" in path.name:
        raise OperatorError("immutable runtime receipt name is unsafe")
    encoded = (json.dumps(payload, indent=2, sort_keys=True) + "\n").encode(
        "utf-8"
    )
    temporary_name = (
        f".{path.name}.create.{os.getpid()}.{os.urandom(16).hex()}"
    )
    flags = (
        os.O_WRONLY
        | os.O_CREAT
        | os.O_EXCL
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    with _anchored_directory_descriptor(path.parent) as observed_directory_fd:
        directory_fd = observed_directory_fd
        if authority_directory_fd is not None:
            if not _same_namespace_identity(
                os.fstat(observed_directory_fd),
                os.fstat(authority_directory_fd),
            ):
                raise OperatorError(
                    "immutable runtime receipt authority directory changed"
                )
            directory_fd = authority_directory_fd
        descriptor = -1
        published = False
        try:
            descriptor = os.open(
                temporary_name,
                flags,
                0o600,
                dir_fd=directory_fd,
            )
            os.fchmod(descriptor, 0o600)
            with os.fdopen(descriptor, "wb") as handle:
                descriptor = -1
                handle.write(encoded)
                handle.flush()
                os.fsync(handle.fileno())
            _rename_noreplace(directory_fd, temporary_name, path.name)
            published = True
            os.fsync(directory_fd)
            read_fd = os.open(
                path.name,
                os.O_RDONLY
                | getattr(os, "O_CLOEXEC", 0)
                | getattr(os, "O_NOFOLLOW", 0)
                | getattr(os, "O_NONBLOCK", 0),
                dir_fd=directory_fd,
            )
            try:
                opened = os.fstat(read_fd)
                observed = bytearray()
                while len(observed) <= len(encoded):
                    chunk = os.read(read_fd, len(encoded) + 1 - len(observed))
                    if not chunk:
                        break
                    observed.extend(chunk)
                after = os.fstat(read_fd)
                named = os.stat(
                    path.name,
                    dir_fd=directory_fd,
                    follow_symlinks=False,
                )
                if (
                    not stat.S_ISREG(opened.st_mode)
                    or opened.st_uid != os.geteuid()
                    or opened.st_nlink != 1
                    or stat.S_IMODE(opened.st_mode) != 0o600
                    or bytes(observed) != encoded
                    or not _same_namespace_identity(opened, after)
                    or not _same_namespace_identity(opened, named)
                ):
                    raise OperatorError(
                        "immutable runtime receipt publication did not verify"
                    )
            finally:
                os.close(read_fd)
        finally:
            if descriptor >= 0:
                os.close(descriptor)
            try:
                os.unlink(temporary_name, dir_fd=directory_fd)
            except FileNotFoundError:
                pass
            if not published:
                os.fsync(directory_fd)
        if authority_directory_fd is not None and not _same_namespace_identity(
            os.fstat(observed_directory_fd),
            os.fstat(authority_directory_fd),
        ):
            raise OperatorError(
                "immutable runtime receipt authority directory changed"
            )


@contextmanager
def _repair_transition_authorization_guard(
    paths: Mapping[str, Path],
) -> Any:
    """Boundedly exclude duplicate validators for the immutable repair chain.

    The stable lock covers validation through receipt publication.  A caller
    that acquires it after a prior publisher has completed re-reads the exact
    immutable receipt through the existing idempotent authorization path; it
    never starts a competing validation or state mutation.
    """

    lock_path = paths.get("repair_transition_authorization_lock")
    if not isinstance(lock_path, Path):
        raise OperatorError("repair-transition authorization lock is absent")
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    from ipfs_accelerate_py.agent_supervisor.runtime.quack_state_server import (
        acquire_exclusive_owner_lock,
    )

    deadline = time.monotonic() + AUTHORIZATION_TRANSITION_LOCK_TIMEOUT_SECONDS
    handle: Any | None = None
    with _anchored_directory_descriptor(lock_path.parent) as anchored_directory:
        while handle is None:
            try:
                handle = acquire_exclusive_owner_lock(lock_path)
            except BlockingIOError:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise OperatorError(
                        "repair_transition_authorization_contended"
                    ) from None
                time.sleep(min(0.05, remaining))

        def verify_authority() -> None:
            assert handle is not None
            handle.assert_canonical_parent()
            opened_directory = os.fstat(handle.directory_fileno())
            if not _same_namespace_identity(
                opened_directory,
                os.fstat(anchored_directory),
            ):
                raise OperatorError(
                    "repair-transition authorization directory changed"
                )
            try:
                named_lock = os.stat(
                    lock_path.name,
                    dir_fd=handle.directory_fileno(),
                    follow_symlinks=False,
                )
            except OSError as exc:
                raise OperatorError(
                    "repair-transition authorization lock name changed"
                ) from exc
            if not _same_namespace_identity(
                named_lock,
                os.fstat(handle.fileno()),
            ):
                raise OperatorError(
                    "repair-transition authorization lock name changed"
                )

        try:
            verify_authority()
            try:
                yield anchored_directory
            finally:
                verify_authority()
        finally:
            handle.close()


@contextmanager
def _r19_historical_live_lifecycle_guard(
    paths: Mapping[str, Path],
) -> Any:
    """Boundedly exclude concurrent R19 historical-live lifecycles.

    The stable lock is independent of the process-local active-policy scope.
    It can therefore fence separate operator processes before either one
    observes or launches the effectful historical validation.  The lock path,
    parent-directory chain, and opened inode remain identity-bound for the
    complete scope.
    """

    lock_path = paths.get("r19_historical_live_lifecycle_lock")
    if not isinstance(lock_path, Path):
        raise OperatorError("R19 historical-live lifecycle lock is absent")
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    from ipfs_accelerate_py.agent_supervisor.runtime.quack_state_server import (
        acquire_exclusive_owner_lock,
    )

    deadline = (
        time.monotonic()
        + R19_HISTORICAL_LIFECYCLE_LOCK_TIMEOUT_SECONDS
    )
    handle: Any | None = None
    with _anchored_directory_descriptor(lock_path.parent) as anchored_directory:
        while handle is None:
            try:
                handle = acquire_exclusive_owner_lock(lock_path)
            except BlockingIOError:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise OperatorError(
                        "r19_historical_live_lifecycle_contended"
                    ) from None
                time.sleep(min(0.05, remaining))

        def verify_authority() -> None:
            assert handle is not None
            handle.assert_canonical_parent()
            opened_directory = os.fstat(handle.directory_fileno())
            if not _same_namespace_identity(
                opened_directory,
                os.fstat(anchored_directory),
            ):
                raise OperatorError(
                    "R19 historical-live lifecycle directory changed"
                )
            try:
                named_lock = os.stat(
                    lock_path.name,
                    dir_fd=handle.directory_fileno(),
                    follow_symlinks=False,
                )
            except OSError as exc:
                raise OperatorError(
                    "R19 historical-live lifecycle lock name changed"
                ) from exc
            if not _same_namespace_identity(
                named_lock,
                os.fstat(handle.fileno()),
            ):
                raise OperatorError(
                    "R19 historical-live lifecycle lock name changed"
                )

        acquired_at_ns = time.time_ns()
        opened_lock = os.fstat(handle.fileno())
        lock_identity: dict[str, Any] = {
            "schema": (
                "ipfs_accelerate_py/agent-supervisor/"
                "aseh-r19-historical-live-lifecycle-lock@1"
            ),
            "path": str(lock_path.relative_to(ROOT)),
            "device": opened_lock.st_dev,
            "inode": opened_lock.st_ino,
            "mode": opened_lock.st_mode,
            "uid": opened_lock.st_uid,
            "nlink": opened_lock.st_nlink,
            "owner_process_birth": _r16_exact_process_birth(os.getpid()),
            "acquired_at_ns": acquired_at_ns,
        }
        lock_identity["lock_identity_cid"] = _identity(lock_identity)
        try:
            verify_authority()
            try:
                yield lock_identity
            finally:
                verify_authority()
        finally:
            handle.close()


def _secure_runtime_json(path: Path, *, max_bytes: int) -> dict[str, Any]:
    """Read one same-UID runtime object through an anchored parent namespace."""

    nofollow = getattr(os, "O_NOFOLLOW", 0)
    if not nofollow:
        raise OperatorError("runtime authority reads require O_NOFOLLOW")
    if path.name in {"", ".", ".."} or "/" in path.name:
        raise OperatorError("runtime authority file name is unsafe")
    with _anchored_directory_descriptor(path.parent) as directory_fd:
        descriptor = os.open(
            path.name,
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NONBLOCK", 0)
            | nofollow,
            dir_fd=directory_fd,
        )
        try:
            opened = os.fstat(descriptor)
            if (
                not stat.S_ISREG(opened.st_mode)
                or opened.st_uid != os.geteuid()
                or opened.st_nlink != 1
                or stat.S_IMODE(opened.st_mode) != 0o600
                or opened.st_size <= 0
                or opened.st_size > max_bytes
            ):
                raise OperatorError("runtime authority file identity is unsafe")
            chunks: list[bytes] = []
            remaining = int(opened.st_size)
            while remaining:
                chunk = os.read(descriptor, min(remaining, 65_536))
                if not chunk:
                    raise OperatorError("runtime authority file was truncated")
                chunks.append(chunk)
                remaining -= len(chunk)
            after = os.fstat(descriptor)
        finally:
            os.close(descriptor)
        path_after = os.stat(
            path.name,
            dir_fd=directory_fd,
            follow_symlinks=False,
        )

    def identity(value: os.stat_result) -> tuple[int, ...]:
        return (
            value.st_dev, value.st_ino, value.st_mode, value.st_uid,
            value.st_nlink, value.st_size, value.st_mtime_ns,
            value.st_ctime_ns,
        )

    if (
        identity(opened) != identity(after)
        or identity(opened) != identity(path_after)
        or stat.S_ISLNK(path_after.st_mode)
    ):
        raise OperatorError("runtime authority file changed during read")
    try:
        payload = json.loads(b"".join(chunks).decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise OperatorError("runtime authority file is not valid JSON") from exc
    if not isinstance(payload, dict):
        raise OperatorError("runtime authority JSON must be an object")
    return payload


def _bootstrap_receipt_id(payload: Mapping[str, Any]) -> str:
    """Validate the closed bootstrap receipt and return its content identity."""

    if (
        payload.get("schema") != BOOTSTRAP_SCHEMA
        or set(payload) != BOOTSTRAP_RECEIPT_FIELDS
    ):
        raise OperatorError("bootstrap receipt schema or fields are invalid")
    unsigned = dict(payload)
    receipt_id = str(unsigned.pop("bootstrap_receipt_id", "") or "")
    if receipt_id != _identity(unsigned):
        raise OperatorError("bootstrap receipt CID is invalid")
    return receipt_id


