def _load_exact_r30_receipt_chain(
    paths: Mapping[str, Path],
) -> list[Mapping[str, Any]]:
    """Load, self-CID-admit, and vector-bind raw R1-R30 receipts."""

    chain = list(_load_exact_r27_receipt_chain(paths))
    r30_path = paths.get("repair_candidate_git_epoch_guard_transition_receipt")
    if not isinstance(r30_path, Path) or not r30_path.is_file():
        raise OperatorError("R31 historical live prior R30 receipt is absent")
    r30_receipt = _secure_runtime_json(
        r30_path,
        max_bytes=STATUS_RECEIPT_MAX_BYTES,
    )
    _repair_candidate_git_epoch_guard_transition_receipt_id(r30_receipt)
    admitted = _admit_exact_r30_transition_chain([*chain, r30_receipt])
    if tuple(
        str(item.get("receipt_cid") or "") for item in admitted
    ) != ASEH_R31_EXACT_R1_R30_RECEIPT_CIDS:
        raise OperatorError("R31 historical live prior receipt vector differs")
    return admitted


def _load_exact_r36_receipt_chain(
    paths: Mapping[str, Path],
) -> list[Mapping[str, Any]]:
    """Load published R1-R30 plus published R36."""

    chain = list(_load_exact_r30_receipt_chain(paths))
    r36_path = paths.get("repair_foreign_grok_terminal_scope_transition_receipt")
    if not isinstance(r36_path, Path) or not r36_path.is_file():
        raise OperatorError("R37 historical live prior R36 receipt is absent")
    r36_receipt = _secure_runtime_json(
        r36_path,
        max_bytes=STATUS_RECEIPT_MAX_BYTES,
    )
    cid = _repair_foreign_grok_terminal_scope_transition_receipt_id(r36_receipt)
    if cid != ASEH_R37_PUBLISHED_R36_RECEIPT_CID:
        raise OperatorError("R37 published R36 receipt identity differs")
    admitted = _admit_exact_r36_transition_chain([*chain, r36_receipt])
    if tuple(
        str(item.get("receipt_cid") or "") for item in admitted
    ) != ASEH_R37_EXACT_R1_R36_RECEIPT_CIDS:
        raise OperatorError("R37 historical live prior receipt vector differs")
    return admitted


