def _r42_reviewed_r11_native_dependency_source() -> Path:
    """Select and inspect the reviewed R11 binary without ambient lookup."""

    from ipfs_accelerate_py.llm_router import (
        inspect_agent_supervisor_native_dependency_source,
    )

    _validate_r42_native_dependency_bootstrap_dispatch_contract(
        _r42_native_dependency_bootstrap_dispatch_contract()
    )
    source = ASEH_R42_REVIEWED_R11_NATIVE_DEPENDENCY_SOURCE
    try:
        before = os.lstat(source)
        if (
            not stat.S_ISREG(before.st_mode)
            or stat.S_ISLNK(before.st_mode)
            or before.st_uid != os.geteuid()
            or before.st_nlink != 1
            or before.st_size != ASEH_R11_NATIVE_DEPENDENCY_PIN["size_bytes"]
            or source.resolve(strict=True) != source
        ):
            raise OperatorError("reviewed R11 native source is unsafe")
        pin = inspect_agent_supervisor_native_dependency_source(
            source,
            distribution_version="1.5.5",
            engine_version="v1.5.5",
        )
        after = os.lstat(source)
    except (OSError, ValueError) as exc:
        raise OperatorError("reviewed R11 native source is unavailable") from exc
    identity_fields = (
        "st_dev", "st_ino", "st_mode", "st_uid", "st_gid", "st_nlink",
        "st_size", "st_mtime_ns", "st_ctime_ns",
    )
    if (
        any(getattr(before, name) != getattr(after, name) for name in identity_fields)
        or pin.as_dict() != ASEH_R11_NATIVE_DEPENDENCY_PIN
    ):
        raise OperatorError("reviewed R11 native source differs")
    return source


