def _projection_matches_events_on_disposable_copy(database: Path) -> bool:
    """Replay projections on a private clone, never on authoritative bytes."""

    import shutil
    import tempfile

    from ipfs_accelerate_py.agent_supervisor.task_sources.database_task_source import (
        DatabaseTaskSource,
    )

    def identity(path: Path) -> tuple[int, int, int, int, int]:
        value = path.stat()
        return (
            int(value.st_dev),
            int(value.st_ino),
            int(value.st_size),
            int(value.st_mtime_ns),
            int(value.st_ctime_ns),
        )

    database_before = identity(database)
    wal = Path(f"{database}.wal")
    wal_before = identity(wal) if wal.is_file() else None
    with tempfile.TemporaryDirectory(prefix="aseh-event-replay-") as raw:
        clone = Path(raw) / database.name
        shutil.copy2(database, clone)
        if wal_before is not None:
            shutil.copy2(wal, Path(f"{clone}.wal"))
        if identity(database) != database_before:
            raise OperatorError("control database changed during private replay copy")
        if (identity(wal) if wal.is_file() else None) != wal_before:
            raise OperatorError("control database WAL changed during private replay copy")
        with DatabaseTaskSource(
            clone,
            owner_id="aseh-private-event-replay",
            install_schema=False,
        ) as replay:
            return replay.projection_matches_events() is True


def _validate_r25_projection_recovery_prestart_admission(
    value: Mapping[str, Any],
    *,
    expected_failure_evidence_cid: str | None = None,
) -> dict[str, Any]:
    """Admit only the exact disposable proof needed before R25 owner start."""

    if not isinstance(value, Mapping):
        raise OperatorError("R25 projection-recovery prestart proof is invalid")
    proof = dict(value)
    fields = {
        "schema",
        "authority",
        "failure_evidence_cid",
        "source_database_observation",
        "source_wal_availability",
        "copy_database_sha256",
        "before_projection_cid",
        "before_event_watermark",
        "before_projection_matches_events",
        "recovery_event_id",
        "recovery_event_global_sequence",
        "recovery_candidates",
        "after_projection_cid",
        "after_event_watermark",
        "strict_projection_matches_events",
        "second_pass_changed",
        "second_pass_event_watermark",
        "second_pass_projection_cid",
        "live_database_mutated",
        "proof_cid",
    }
    candidates = proof.get("recovery_candidates")
    expected = [
        dict(item)
        for item in ASEH_R25_EXACT_LEGACY_PROJECTION_RECOVERY_CANDIDATES
    ]
    normalized: list[dict[str, Any]] = []
    if isinstance(candidates, list):
        for item in candidates:
            if not isinstance(item, Mapping):
                break
            normalized.append(
                {
                    "task_alias": str(item.get("task_alias") or ""),
                    "legacy_status": str(item.get("legacy_status") or ""),
                    "legacy_revision": item.get("legacy_revision"),
                    "admitted_status": str(item.get("admitted_status") or ""),
                    "admitted_revision": item.get("admitted_revision"),
                }
            )
    normalized.sort(key=lambda item: item["task_alias"])
    observation = proof.get("source_database_observation")
    unsigned = dict(proof)
    proof_cid = str(unsigned.pop("proof_cid", "") or "")
    if (
        set(proof) != fields
        or proof.get("schema")
        != ASEH_R25_PROJECTION_RECOVERY_PRESTART_ADMISSION_SCHEMA
        or proof.get("authority") != "non_authoritative_disposable_copy"
        or (
            expected_failure_evidence_cid is not None
            and proof.get("failure_evidence_cid")
            != expected_failure_evidence_cid
        )
        or re.fullmatch(
            r"sha256:[0-9a-f]{64}",
            str(proof.get("failure_evidence_cid") or ""),
        )
        is None
        or not isinstance(observation, Mapping)
        or observation.get("availability") != "observed"
        or proof.get("source_wal_availability") != "absent"
        or proof.get("copy_database_sha256") != observation.get("sha256")
        or proof.get("before_projection_matches_events") is not False
        or normalized != expected
        or proof.get("strict_projection_matches_events") is not True
        or proof.get("second_pass_changed") is not False
        or proof.get("live_database_mutated") is not False
        or not str(proof.get("recovery_event_id") or "").startswith("bag")
        or type(proof.get("before_event_watermark")) is not int
        or type(proof.get("recovery_event_global_sequence")) is not int
        or type(proof.get("after_event_watermark")) is not int
        or type(proof.get("second_pass_event_watermark")) is not int
        or proof.get("recovery_event_global_sequence")
        != proof.get("after_event_watermark")
        or proof.get("after_event_watermark")
        != proof.get("second_pass_event_watermark")
        or proof.get("after_projection_cid")
        != proof.get("second_pass_projection_cid")
        or proof_cid != _identity(unsigned)
    ):
        raise OperatorError("R25 projection-recovery prestart proof differs")
    return proof


def _r25_projection_recovery_on_disposable_copy(
    database: Path,
    *,
    expected_database_observation: Mapping[str, Any],
    failure_evidence_cid: str,
) -> dict[str, Any]:
    """Prove the exact R24 drift and its idempotent repair on private bytes."""

    import shutil
    import tempfile

    from ipfs_accelerate_py.agent_supervisor.task_sources.intent_repository import (
        IntentRepository,
        IntentRepositoryIntegrityError,
    )

    directory_fd = os.open(
        database.parent,
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0),
    )
    try:
        source_before = _r21_owner_start_file_observation(
            directory_fd, database.name
        )
        wal_name = f"{database.name}.wal"
        wal_before = _r21_owner_start_file_observation(directory_fd, wal_name)
        if (
            source_before != dict(expected_database_observation)
            or wal_before.get("availability") != "absent"
        ):
            raise OperatorError(
                "R25 prestart database differs from the admitted failed R24 bytes"
            )
        with tempfile.TemporaryDirectory(prefix="aseh-r25-projection-recovery-") as raw:
            clone = Path(raw) / database.name
            shutil.copy2(database, clone)
            os.chmod(clone, 0o600)
            clone_fd = os.open(
                clone.parent,
                os.O_RDONLY
                | getattr(os, "O_DIRECTORY", 0)
                | getattr(os, "O_CLOEXEC", 0),
            )
            try:
                clone_observation = _r21_owner_start_file_observation(
                    clone_fd, clone.name
                )
            finally:
                os.close(clone_fd)
            if (
                clone_observation.get("sha256") != source_before.get("sha256")
                or clone_observation.get("size_bytes")
                != source_before.get("size_bytes")
            ):
                raise OperatorError("R25 disposable database copy differs")

            repository = IntentRepository(
                clone,
                owner_id="aseh-r25-private-projection-recovery",
                session_id="aseh-r25-private-projection-recovery",
                install_schema=False,
            )
            try:
                before = repository.snapshot()
                try:
                    repository.assert_projection_matches_events()
                except IntentRepositoryIntegrityError:
                    pass
                else:
                    raise OperatorError(
                        "R25 prestart database has no projection drift to recover"
                    )
                recovery = repository.reconcile_legacy_stale_unstall_projection_drift()
                candidates = [
                    dict(item)
                    for item in (recovery.details.get("candidates") or ())
                    if isinstance(item, Mapping)
                ]
                candidates.sort(key=lambda item: str(item.get("task_alias") or ""))
                after = repository.assert_projection_matches_events()
                second = repository.reconcile_legacy_stale_unstall_projection_drift()
                second_after = repository.assert_projection_matches_events()
            finally:
                repository.close()
    except IntentRepositoryIntegrityError as exc:
        raise OperatorError(
            "R25 prestart database is not the bounded legacy projection drift"
        ) from exc
    finally:
        source_after = _r21_owner_start_file_observation(
            directory_fd, database.name
        )
        wal_after = _r21_owner_start_file_observation(directory_fd, wal_name)
        os.close(directory_fd)
    if source_after != source_before or wal_after != wal_before:
        raise OperatorError("live database changed during R25 disposable replay")
    proof: dict[str, Any] = {
        "schema": ASEH_R25_PROJECTION_RECOVERY_PRESTART_ADMISSION_SCHEMA,
        "authority": "non_authoritative_disposable_copy",
        "failure_evidence_cid": failure_evidence_cid,
        "source_database_observation": dict(source_before),
        "source_wal_availability": "absent",
        "copy_database_sha256": str(clone_observation["sha256"]),
        "before_projection_cid": before.projection_cid,
        "before_event_watermark": before.event_watermark,
        "before_projection_matches_events": False,
        "recovery_event_id": recovery.event_id,
        "recovery_event_global_sequence": recovery.global_sequence,
        "recovery_candidates": candidates,
        "after_projection_cid": after.projection_cid,
        "after_event_watermark": after.event_watermark,
        "strict_projection_matches_events": True,
        "second_pass_changed": second.changed,
        "second_pass_event_watermark": second_after.event_watermark,
        "second_pass_projection_cid": second_after.projection_cid,
        "live_database_mutated": False,
    }
    proof["proof_cid"] = _identity(proof)
    return _validate_r25_projection_recovery_prestart_admission(
        proof,
        expected_failure_evidence_cid=failure_evidence_cid,
    )


def _r26_projection_recovery_on_disposable_copy(
    database: Path,
    *,
    expected_database_observation: Mapping[str, Any],
    failure_evidence_cid: str,
    preflight_failure_evidence_cid: str,
) -> dict[str, Any]:
    """Prove R26's corrected vector on private bytes with a stable identity."""

    import shutil
    import tempfile

    from ipfs_accelerate_py.agent_supervisor.task_sources.intent_repository import (
        IntentRepository,
        IntentRepositoryIntegrityError,
    )

    directory_fd = os.open(
        database.parent,
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0),
    )
    try:
        source_before = _r21_owner_start_file_observation(
            directory_fd, database.name
        )
        wal_name = f"{database.name}.wal"
        wal_before = _r21_owner_start_file_observation(directory_fd, wal_name)
        if (
            source_before != dict(expected_database_observation)
            or wal_before.get("availability") != "absent"
        ):
            raise OperatorError(
                "R26 prestart database differs from the admitted failed R24 bytes"
            )
        with tempfile.TemporaryDirectory(prefix="aseh-r26-projection-recovery-") as raw:
            clone = Path(raw) / database.name
            shutil.copy2(database, clone)
            os.chmod(clone, 0o600)
            clone_fd = os.open(
                clone.parent,
                os.O_RDONLY
                | getattr(os, "O_DIRECTORY", 0)
                | getattr(os, "O_CLOEXEC", 0),
            )
            try:
                clone_observation = _r21_owner_start_file_observation(
                    clone_fd, clone.name
                )
            finally:
                os.close(clone_fd)
            if (
                clone_observation.get("sha256") != source_before.get("sha256")
                or clone_observation.get("size_bytes")
                != source_before.get("size_bytes")
            ):
                raise OperatorError("R26 disposable database copy differs")

            repository = IntentRepository(
                clone,
                owner_id="aseh-r26-private-projection-recovery",
                session_id="aseh-r26-private-projection-recovery",
                install_schema=False,
            )
            try:
                before = repository.snapshot()
                try:
                    repository.assert_projection_matches_events()
                except IntentRepositoryIntegrityError:
                    pass
                else:
                    raise OperatorError(
                        "R26 prestart database has no projection drift to recover"
                    )
                recovery = repository.reconcile_legacy_stale_unstall_projection_drift()
                candidates = [
                    dict(item)
                    for item in (recovery.details.get("candidates") or ())
                    if isinstance(item, Mapping)
                ]
                candidates.sort(key=lambda item: str(item.get("task_alias") or ""))
                after = repository.assert_projection_matches_events()
                second = repository.reconcile_legacy_stale_unstall_projection_drift()
                second_after = repository.assert_projection_matches_events()
            finally:
                repository.close()
    except IntentRepositoryIntegrityError as exc:
        raise OperatorError(
            "R26 prestart database is not the bounded legacy projection drift"
        ) from exc
    finally:
        source_after = _r21_owner_start_file_observation(
            directory_fd, database.name
        )
        wal_after = _r21_owner_start_file_observation(directory_fd, wal_name)
        os.close(directory_fd)
    if source_after != source_before or wal_after != wal_before:
        raise OperatorError("live database changed during R26 disposable replay")
    proof: dict[str, Any] = {
        "schema": ASEH_R26_PROJECTION_RECOVERY_PRESTART_ADMISSION_SCHEMA,
        "authority": "non_authoritative_disposable_copy",
        "failure_evidence_cid": failure_evidence_cid,
        "r25_preflight_failure_evidence_cid": preflight_failure_evidence_cid,
        "source_database_observation": dict(source_before),
        "source_wal_availability": "absent",
        "copy_database_sha256": str(clone_observation["sha256"]),
        "before_projection_cid": before.projection_cid,
        "before_event_watermark": before.event_watermark,
        "before_projection_matches_events": False,
        "recovery_event_id": recovery.event_id,
        "recovery_event_global_sequence": recovery.global_sequence,
        "recovery_candidates": candidates,
        "after_projection_cid": after.projection_cid,
        "after_event_watermark": after.event_watermark,
        "strict_projection_matches_events": True,
        "second_pass_changed": second.changed,
        "second_pass_event_watermark": second_after.event_watermark,
        "second_pass_projection_cid": second_after.projection_cid,
        "live_database_mutated": False,
    }
    proof["semantic_admission_cid"] = _identity(
        _r26_projection_recovery_semantic_admission(proof)
    )
    proof["proof_cid"] = _identity(proof)
    return _validate_r26_projection_recovery_prestart_admission(
        proof,
        expected_failure_evidence_cid=failure_evidence_cid,
        expected_preflight_failure_evidence_cid=(
            preflight_failure_evidence_cid
        ),
    )


@contextmanager
def _read_only_database_task_source(
    database: Path,
    *,
    owner_id: str,
    repository_tree_id: str,
    plan_root_cid: str,
) -> Any:
    """Bind DatabaseTaskSource reads to one policy-locked read-only handle."""

    from ipfs_accelerate_py.agent_supervisor.task_sources.database_task_source import (
        DatabaseTaskSource,
    )
    from ipfs_accelerate_py.agent_supervisor.task_sources.duckdb_state import (
        connect_duckdb_with_policy,
    )
    from ipfs_accelerate_py.agent_supervisor.task_sources.intent_repository import (
        open_intent_repository,
    )

    import duckdb

    connection = connect_duckdb_with_policy(duckdb, database, read_only=True)
    source: DatabaseTaskSource | None = None
    try:
        intent = open_intent_repository(
            database,
            bound_connection=connection,
            owner_id=owner_id,
            install_schema=False,
        )
        source = DatabaseTaskSource(
            intent=intent,
            owner_id=owner_id,
            repository_tree_id=repository_tree_id,
            plan_root_cid=plan_root_cid,
        )
        yield source
    finally:
        if source is not None:
            source.close()
        connection.close()


def _read_continuity_state(
    board: Any,
    paths: Mapping[str, Path],
    bootstrap: Mapping[str, Any],
    *,
    r25_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r26_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r27_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r28_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r29_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r30_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r31_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r36_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r37_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r38_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r39_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r40_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r45_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r44_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r43_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r42_projection_recovery_prequalification: Mapping[str, Any] | None = None,
    r41_projection_recovery_prequalification: Mapping[str, Any] | None = None,
) -> tuple[
    dict[str, Any],
    list[str],
    dict[str, Any],
    dict[str, tuple[str, ...]],
    tuple[Any, ...],
    dict[str, Any] | None,
]:
    """Take one mutually excluded read-only DB and merge-queue snapshot."""

    with _offline_database_guard(paths):
        with _offline_merge_queue_guard(paths) as queue_database:
            recovery_admission: dict[str, Any] | None = None
            r26_projection_bundle = (
                r45_projection_recovery_prequalification
                or r44_projection_recovery_prequalification
                or r43_projection_recovery_prequalification
                or r42_projection_recovery_prequalification
                or r41_projection_recovery_prequalification
                or r40_projection_recovery_prequalification
                or r39_projection_recovery_prequalification
                or r38_projection_recovery_prequalification
                or r37_projection_recovery_prequalification
                or r36_projection_recovery_prequalification
                or r31_projection_recovery_prequalification
                or r30_projection_recovery_prequalification
                or r29_projection_recovery_prequalification
                or r28_projection_recovery_prequalification
                or r27_projection_recovery_prequalification
                or r26_projection_recovery_prequalification
            )
            if r26_projection_bundle is not None:
                projection_matches = (
                    _projection_matches_events_on_disposable_copy(
                        paths["database"]
                    )
                )
                if not projection_matches:
                    receipt = r26_projection_bundle.get("receipt")
                    failure_value = (
                        receipt.get("projection_recovery_failure_evidence")
                        if isinstance(receipt, Mapping)
                        else None
                    )
                    preflight_value = (
                        receipt.get("r25_preflight_failure_evidence")
                        if isinstance(receipt, Mapping)
                        else None
                    )
                    failure = (
                        _validate_r25_projection_recovery_failure_evidence(
                            failure_value
                        )
                        if isinstance(failure_value, Mapping)
                        else None
                    )
                    preflight = (
                        _validate_r26_r25_preflight_failure_evidence(
                            preflight_value
                        )
                        if isinstance(preflight_value, Mapping)
                        else None
                    )
                    if not isinstance(failure, Mapping) or not isinstance(
                        preflight, Mapping
                    ):
                        raise OperatorError(
                            "R26 prestart projection-recovery evidence is absent"
                        )
                    recovery_admission = (
                        _r26_projection_recovery_on_disposable_copy(
                            paths["database"],
                            expected_database_observation=failure[
                                "database_after_failed_launch"
                            ],
                            failure_evidence_cid=str(failure["evidence_cid"]),
                            preflight_failure_evidence_cid=str(
                                preflight["evidence_cid"]
                            ),
                        )
                    )
            elif r25_projection_recovery_prequalification is not None:
                projection_matches = (
                    _projection_matches_events_on_disposable_copy(
                        paths["database"]
                    )
                )
                if not projection_matches:
                    receipt = r25_projection_recovery_prequalification.get(
                        "receipt"
                    )
                    failure_value = (
                        receipt.get("projection_recovery_failure_evidence")
                        if isinstance(receipt, Mapping)
                        else None
                    )
                    failure = (
                        _validate_r25_projection_recovery_failure_evidence(
                            failure_value
                        )
                        if isinstance(failure_value, Mapping)
                        else None
                    )
                    if not isinstance(failure, Mapping):
                        raise OperatorError(
                            "R25 prestart projection-recovery evidence is absent"
                        )
                    recovery_admission = (
                        _r25_projection_recovery_on_disposable_copy(
                            paths["database"],
                            expected_database_observation=failure[
                                "database_after_failed_launch"
                            ],
                            failure_evidence_cid=str(failure["evidence_cid"]),
                        )
                    )
            else:
                projection_matches = _projection_matches_events_on_disposable_copy(
                    paths["database"]
                )
            with _read_only_database_task_source(
                paths["database"],
                owner_id="aseh-launch-continuity:read-only",
                repository_tree_id=str(bootstrap["repository_tree_id"]),
                plan_root_cid=str(bootstrap["plan_root_cid"]),
            ) as source:
                snapshot, ready, integrity, outputs = (
                    _verify_materialized_source_from_bootstrap(
                        source,
                        bootstrap=bootstrap,
                        projection_matches_events=projection_matches,
                        projection_recovery_prestart_admission=(
                            recovery_admission
                        ),
                    )
                )
            requests = _read_completed_merge_requests(queue_database)
    return snapshot, ready, integrity, outputs, requests, recovery_admission


def _admit_repair_followup_base(
    board: Any,
    *,
    bootstrap: Mapping[str, Any],
    integrity: Mapping[str, Any],
    task_outputs: Mapping[str, Sequence[str]],
    completed_requests: Sequence[Any],
    stored_followup: Mapping[str, Any] | None = None,
    require_nonterminal: bool = False,
) -> dict[str, Any]:
    """Admit exact integrated bytes without converting them to completion."""

    statuses = integrity.get("task_statuses")
    revisions = integrity.get("task_revisions")
    task_cids = integrity.get("task_cids")
    alias = REPAIR_FOLLOWUP_TRANSITION_TASK_ALIAS
    if not all(
        isinstance(value, Mapping) for value in (statuses, revisions, task_cids)
    ):
        raise OperatorError("follow-up lifecycle authority is incomplete")
    status = str(statuses.get(alias) or "").strip().casefold()
    revision = revisions.get(alias)
    task_cid = str(task_cids.get(alias) or "")
    if type(revision) is not int or not task_cid:
        raise OperatorError("follow-up lifecycle identity is incomplete")
    historical: Mapping[str, Any] = {}
    stored_witness: Mapping[str, Any] = {}
    if stored_followup is not None:
        raw_historical = stored_followup.get("authorization_task_observation")
        raw_witness = stored_followup.get("base_integration_witness")
        if not isinstance(raw_historical, Mapping) or not isinstance(
            raw_witness, Mapping
        ):
            raise OperatorError("follow-up historical evidence is absent")
        historical = raw_historical
        stored_witness = raw_witness
        if (
            historical.get("task_cid") != task_cid
            or type(historical.get("revision")) is not int
            or revision < int(historical["revision"])
            or (
                revision == int(historical["revision"])
                and status != str(historical.get("status") or "")
            )
            or stored_witness.get("task_cid") != task_cid
        ):
            raise OperatorError("follow-up task identity or revision regressed")
    if require_nonterminal and status not in {"blocked", "retrying"}:
        raise OperatorError(
            "follow-up authorization requires blocked or retrying ASEH-001"
        )
    witness_proof = _admit_canonical_merge_suffix(
        board,
        base_head=REPAIR_FOLLOWUP_TRANSITION_FIRST_PARENT,
        target_head=REPAIR_FOLLOWUP_TRANSITION_BASE_HEAD,
        bootstrap=bootstrap,
        integrity=integrity,
        task_outputs=task_outputs,
        completed_requests=completed_requests,
        admission_mode="followup_repair_base",
    )
    witness, current_observation = _repair_followup_witness_from_proof(
        witness_proof
    )
    if stored_followup is not None and witness != dict(stored_witness):
        raise OperatorError("follow-up immutable integration witness drifted")
    result = {
        "schema": (
            "ipfs_accelerate_py/agent-supervisor/"
            "aseh-followup-base-continuity@1"
        ),
        "admission": "immutable_integration_witness",
        "task_completion_admitted": False,
        "proof": witness_proof,
        "base_integration_witness": witness,
        "authorization_task_observation": (
            dict(historical)
            if stored_followup is not None
            else current_observation
        ),
    }
    if status in COMPLETED_STATUSES:
        result["canonical_completion_proof"] = _admit_canonical_merge_suffix(
            board,
            base_head=REPAIR_FOLLOWUP_TRANSITION_FIRST_PARENT,
            target_head=REPAIR_FOLLOWUP_TRANSITION_BASE_HEAD,
            bootstrap=bootstrap,
            integrity=integrity,
            task_outputs=task_outputs,
            completed_requests=completed_requests,
        )
        result["admission"] = "canonical_completion"
        result["task_completion_admitted"] = True
    return result


def _r14_native_seal_anchor(
    paths: Mapping[str, Path],
    *,
    current_head: str,
) -> dict[str, Any] | None:
    """Select the admitted R14 historical anchor for native-byte sealing.

    R15 and later candidates remain separately live-witnessed and launch-
    admitted; they deliberately reuse R14's already-admitted R11 native-byte
    authorization rather than minting another native authority.
    """

    r14_path = paths.get(
        "repair_sealed_receipt_validation_transition_receipt"
    )
    if isinstance(r14_path, Path) and r14_path.is_file():
        receipt = _secure_runtime_json(
            r14_path,
            max_bytes=STATUS_RECEIPT_MAX_BYTES,
        )
        head = receipt.get("repair_head")
        tree = receipt.get("repair_tree")
        witness = receipt.get("candidate_authorization_witness")
        if (
            not isinstance(head, str)
            or not isinstance(tree, str)
            or not isinstance(witness, Mapping)
        ):
            raise OperatorError("R14 native-seal anchor is incomplete")
        _git("merge-base", "--is-ancestor", head, current_head)
        return {"head": head, "tree": tree, "witness": dict(witness)}
    parents = _git("show", "-s", "--format=%P", current_head).split()
    if parents != [REPAIR_SEALED_RECEIPT_VALIDATION_TRANSITION_BASE_HEAD]:
        return None
    r13_path = paths.get(
        "repair_validation_executor_identity_transition_receipt"
    )
    if not isinstance(r13_path, Path) or not r13_path.is_file():
        raise OperatorError("R13 native-seal anchor is absent")
    receipt = _secure_runtime_json(
        r13_path,
        max_bytes=STATUS_RECEIPT_MAX_BYTES,
    )
    head = receipt.get("repair_head")
    tree = receipt.get("repair_tree")
    witness = receipt.get("candidate_authorization_witness")
    if (
        head != REPAIR_SEALED_RECEIPT_VALIDATION_TRANSITION_BASE_HEAD
        or not isinstance(tree, str)
        or not isinstance(witness, Mapping)
    ):
        raise OperatorError("R13 native-seal anchor differs")
    return {"head": head, "tree": tree, "witness": dict(witness)}


def authorize_repair_transition(config_path: Path) -> dict[str, Any]:
    """Authorize the one user-directed bootstrap repair after it is committed."""

    from ipfs_accelerate_py.agent_supervisor.runtime.multi_supervisor_runner import (
        retain_control_plane_interpreter,
        trusted_system_dependency_directories_json,
    )

    board, _config = _load(config_path)
    paths = _paths(board)
    with _repair_transition_authorization_guard(
        paths
    ) as authorization_directory_fd:
        candidate_head, candidate_tree = _assert_clean_tree(board)
        with _repair_authorization_candidate_git_guard_if_required(
            paths=paths,
            candidate_head=candidate_head,
            candidate_tree=candidate_tree,
        ):
            anchor = _r14_native_seal_anchor(
                paths,
                current_head=candidate_head,
            )
            if anchor is None:
                return _authorize_repair_transition_locked(
                    board=board,
                    config=_config,
                    paths=paths,
                    authorization_directory_fd=authorization_directory_fd,
                )
            authorization_witness = _candidate_authorization_witness(
                expected_head=candidate_head,
                expected_tree=candidate_tree,
            )
            qualification_home = _build_aseh_qualification_home(paths)
            interpreter = None
            native_dependency = None
            try:
                interpreter = retain_control_plane_interpreter(
                    ASEH_RECEIPT_VALIDATION_PYTHON
                )
                native_dependency = _seal_r11_native_dependency(
                    paths=paths,
                    candidate_head=str(anchor["head"]),
                    candidate_tree=str(anchor["tree"]),
                    candidate_authorization_witness=dict(anchor["witness"]),
                    launch_admission=None,
                    active_candidate_head=candidate_head,
                    active_candidate_tree=candidate_tree,
                    active_candidate_authorization_witness=(
                        authorization_witness
                    ),
                )
                system_directories_json = (
                    trusted_system_dependency_directories_json()
                )
                with _sealed_receipt_validation_executor_scope(
                    interpreter=interpreter,
                    native_dependency=native_dependency,
                    system_dependency_directories_json=(
                        system_directories_json
                    ),
                    candidate_head=candidate_head,
                    candidate_tree=candidate_tree,
                    authorization_witness=authorization_witness,
                    base_environment=_sealed_owner_delegation_environment(
                        qualification_home
                    ),
                ):
                    return _authorize_repair_transition_locked(
                        board=board,
                        config=_config,
                        paths=paths,
                        authorization_directory_fd=(
                            authorization_directory_fd
                        ),
                    )
            finally:
                if native_dependency is not None:
                    try:
                        os.close(native_dependency.descriptor.descriptor)
                    except OSError:
                        pass
                if interpreter is not None:
                    try:
                        os.close(interpreter.descriptor)
                    except OSError:
                        pass


def _authorize_repair_sealed_owner_identity_transition_if_applicable(
    *,
    board: Any,
    config: Mapping[str, Any],
    paths: Mapping[str, Path],
    bootstrap: Mapping[str, Any],
    bootstrap_id: str,
    head: str,
    previous_receipt: Mapping[str, Any],
    previous_transition: Mapping[str, Any],
    prior_receipt_chain: Sequence[Mapping[str, Any]],
    authorization_directory_fd: int,
) -> dict[str, Any] | None:
    """Authorize the one bounded R12 child after the fully admitted R11 chain."""

    r12_path = paths.get("repair_sealed_owner_identity_transition_receipt")
    if not isinstance(r12_path, Path):
        return None
    prior_chain = list(prior_receipt_chain)
    if (
        len(prior_chain) != 11
        or prior_chain[-1].get("receipt_cid")
        != previous_transition.get("receipt_cid")
        or previous_transition.get("repair_head")
        != REPAIR_SEALED_OWNER_IDENTITY_TRANSITION_BASE_HEAD
    ):
        raise OperatorError(
            "bootstrap repair sealed-owner-identity prior chain differs"
        )
    if r12_path.is_file():
        receipt = _secure_runtime_json(
            r12_path,
            max_bytes=STATUS_RECEIPT_MAX_BYTES,
        )
        transition = _validate_repair_sealed_owner_identity_transition(
            receipt,
            bootstrap=bootstrap,
            previous_receipt=previous_receipt,
            rerun_validations=receipt.get("repair_head") == head,
        )
        _git(
            "merge-base",
            "--is-ancestor",
            str(transition["repair_head"]),
            head,
        )
        r13_result = (
            _authorize_repair_validation_executor_identity_transition_if_applicable(
                board=board,
                config=config,
                paths=paths,
                bootstrap=bootstrap,
                bootstrap_id=bootstrap_id,
                head=head,
                previous_receipt=receipt,
                previous_transition=transition,
                prior_receipt_chain=[*prior_chain, receipt],
                authorization_directory_fd=authorization_directory_fd,
            )
        )
        if r13_result is not None:
            return r13_result
        current_admission = _admit_materialized_launch(
            board, config, paths
        )
        admitted_repair = current_admission.get("repair_transition")
        admitted_chain = current_admission.get("repair_transition_chain")
        admitted_continuity = current_admission.get("canonical_continuity")
        expected_chain = [*prior_chain, receipt]
        if (
            not isinstance(admitted_repair, Mapping)
            or admitted_repair.get("schema")
            != REPAIR_SEALED_OWNER_IDENTITY_TRANSITION_SCHEMA
            or admitted_repair.get("repair_head")
            != transition.get("repair_head")
            or admitted_repair.get("receipt_cid")
            != transition.get("receipt_cid")
            or not isinstance(admitted_chain, list)
            or [item.get("receipt_cid") for item in admitted_chain]
            != [item.get("receipt_cid") for item in expected_chain]
            or not isinstance(admitted_continuity, Mapping)
            or "provider_cleanup_fence_to_sealed_owner_identity"
            not in admitted_continuity
        ):
            raise OperatorError(
                "current admission does not retain the sealed-owner-identity "
                "repair transition"
            )
        return {
            "schema": OPERATOR_SCHEMA,
            "command": "authorize-repair-transition",
            "ok": True,
            "idempotent_replay": True,
            "repair_transition_receipt": receipt,
            "repair_transition_chain": expected_chain,
            "current_admission_cid": current_admission["admission_cid"],
            "runtime_source_head": current_admission[
                "runtime_source_head"
            ],
        }
    parents = _git("show", "-s", "--format=%P", head).split()
    if parents != [REPAIR_SEALED_OWNER_IDENTITY_TRANSITION_BASE_HEAD]:
        return None
    if _git_changed_paths(
        REPAIR_SEALED_OWNER_IDENTITY_TRANSITION_BASE_HEAD,
        head,
    ) != REPAIR_SEALED_OWNER_IDENTITY_TRANSITION_CHANGED_PATHS:
        raise OperatorError(
            "bootstrap repair sealed-owner-identity changed-path set differs"
        )
    candidate_tree = _git("rev-parse", f"{head}^{{tree}}")
    authorization_witness = _candidate_authorization_witness(
        expected_head=head,
        expected_tree=candidate_tree,
    )
    validation_results = (
        _run_repair_sealed_owner_identity_transition_validations(
            candidate_head=head,
            candidate_tree=candidate_tree,
            authorization_witness=authorization_witness,
        )
    )
    _assert_candidate_authorization_witness(
        authorization_witness,
        expected_head=head,
        expected_tree=candidate_tree,
        boundary="after R12 validation before receipt publication",
    )
    receipt = {
        "schema": REPAIR_SEALED_OWNER_IDENTITY_TRANSITION_SCHEMA,
        "task_id": REPAIR_TRANSITION_TASK_ID,
        "stable_identity": (
            f"{PROGRAM}/{REPAIR_TRANSITION_TASK_ID}@ASEH-PLAN-R12"
        ),
        "program_id": PROGRAM,
        "transition_revision": 12,
        "bootstrap_receipt_id": bootstrap_id,
        "previous_receipt_cid": previous_transition["receipt_cid"],
        "plan_root_cid": bootstrap["plan_root_cid"],
        "repository_tree_id": bootstrap["repository_tree_id"],
        "base_head": REPAIR_SEALED_OWNER_IDENTITY_TRANSITION_BASE_HEAD,
        "base_tree": _git(
            "rev-parse",
            REPAIR_SEALED_OWNER_IDENTITY_TRANSITION_BASE_HEAD + "^{tree}",
        ),
        "repair_head": head,
        "repair_tree": candidate_tree,
        "changed_paths": list(
            REPAIR_SEALED_OWNER_IDENTITY_TRANSITION_CHANGED_PATHS
        ),
        "patch_digest": _git_patch_digest(
            REPAIR_SEALED_OWNER_IDENTITY_TRANSITION_BASE_HEAD,
            head,
        ),
        "dependencies": ["ASEH-BOOTSTRAP-002@ASEH-PLAN-R11"],
        "owning_repository": "ipfs_accelerate_py",
        "risk_class": "R4_SECURITY_OR_PROTOCOL_SENSITIVE",
        "authority_requirement": (
            REPAIR_SEALED_OWNER_IDENTITY_TRANSITION_AUTHORITY
        ),
        "validation_results": validation_results,
        "candidate_authorization_witness": dict(authorization_witness),
        "terminal_success_criteria": (
            REPAIR_SEALED_OWNER_IDENTITY_TRANSITION_SUCCESS
        ),
        "terminal_non_success_criteria": (
            REPAIR_SEALED_OWNER_IDENTITY_TRANSITION_NON_SUCCESS
        ),
        "semantic_corpus_changed": False,
        "database_mutated": False,
        "authorized_at": time.time(),
    }
    receipt["receipt_cid"] = _identity(receipt)
    _validate_repair_sealed_owner_identity_transition(
        receipt,
        bootstrap=bootstrap,
        previous_receipt=previous_receipt,
        rerun_validations=False,
    )
    _assert_candidate_authorization_witness(
        authorization_witness,
        expected_head=head,
        expected_tree=candidate_tree,
        boundary="immediately before R12 receipt publication",
    )
    _atomic_json_create(
        r12_path,
        receipt,
        authority_directory_fd=authorization_directory_fd,
    )
    _assert_candidate_authorization_witness(
        authorization_witness,
        expected_head=head,
        expected_tree=candidate_tree,
        boundary="after R12 receipt publication",
    )
    return {
        "schema": OPERATOR_SCHEMA,
        "command": "authorize-repair-transition",
        "ok": True,
        "idempotent_replay": False,
        "repair_transition_receipt": receipt,
        "repair_transition_chain": [*prior_chain, receipt],
        "runtime_source_head": head,
    }


